import React, { useState } from 'react';
import { TransactionService } from '../services/transactionService';

const SendMoney = () => {
  const [formData, setFormData] = useState({
    recipientName: '',
    accountNumber: '',
    bankName: '',
    swiftCode: '',
    amount: '',
    currency: 'USD',
    description: ''
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value
    }));
  };

  const validateForm = () => {
    if (!formData.recipientName || !formData.accountNumber || !formData.amount) {
      setError('Please fill in all required fields');
      return false;
    }
    if (isNaN(formData.amount) || formData.amount <= 0) {
      setError('Please enter a valid amount');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setSuccess(false);

    if (!validateForm()) {
      return;
    }

    try {
      setLoading(true);
      const response = await TransactionService.sendMoney(formData);
      setSuccess(true);
      setFormData({
        recipientName: '',
        accountNumber: '',
        bankName: '',
        swiftCode: '',
        amount: '',
        currency: 'USD',
        description: ''
      });
      // You might want to show a success message or redirect
    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="send-money-container">
      <h2>Send Money</h2>

      {error && <div className="error-message">{error}</div>}
      {success && <div className="success-message">Money sent successfully!</div>}

      <form onSubmit={handleSubmit} className="send-money-form">
        <div className="form-group">
          <label htmlFor="recipientName">Recipient's Full Name *</label>
          <input
            type="text"
            id="recipientName"
            name="recipientName"
            value={formData.recipientName}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="accountNumber">Account Number *</label>
          <input
            type="text"
            id="accountNumber"
            name="accountNumber"
            value={formData.accountNumber}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="bankName">Bank Name</label>
          <input
            type="text"
            id="bankName"
            name="bankName"
            value={formData.bankName}
            onChange={handleChange}
          />
        </div>

        <div className="form-group">
          <label htmlFor="swiftCode">SWIFT/BIC Code</label>
          <input
            type="text"
            id="swiftCode"
            name="swiftCode"
            value={formData.swiftCode}
            onChange={handleChange}
          />
        </div>

        <div className="form-group">
          <label htmlFor="amount">Amount *</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={formData.amount}
            onChange={handleChange}
            required
            min="0"
            step="0.01"
          />
        </div>

        <div className="form-group">
          <label htmlFor="currency">Currency</label>
          <select
            id="currency"
            name="currency"
            value={formData.currency}
            onChange={handleChange}
          >
            <option value="USD">USD</option>
            <option value="EUR">EUR</option>
            <option value="GBP">GBP</option>
            {/* Add more currencies as needed */}
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="description">Description</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            rows="3"
          />
        </div>

        <button 
          type="submit" 
          className="submit-button"
          disabled={loading}
        >
          {loading ? 'Processing...' : 'Send Money'}
        </button>
      </form>
    </div>
  );
};

export default SendMoney;
